import{_ as t,o,c as d,a5 as s}from"./chunks/framework.0V7P45eC.js";const u=JSON.parse('{"title":"Coming from Fuse.js, fuzzysort, match-sorter, string-similarity or leven","description":"The fuzzy-toolkit equivalent of every call of Fuse.js, fuzzysort, match-sorter, string-similarity, fastest-levenshtein and leven, side by side, with what changes.","frontmatter":{"title":"Coming from Fuse.js, fuzzysort, match-sorter, string-similarity or leven","description":"The fuzzy-toolkit equivalent of every call of Fuse.js, fuzzysort, match-sorter, string-similarity, fastest-levenshtein and leven, side by side, with what changes."},"headers":[],"relativePath":"guide/coming-from.md","filePath":"guide/coming-from.md","lastUpdated":1795826893000}'),a={name:"guide/coming-from.md"};function r(i,e,c,n,h,l){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="coming-from-another-library" tabindex="-1">Coming from another library <a class="header-anchor" href="#coming-from-another-library" aria-label="Permalink to &quot;Coming from another library&quot;">​</a></h1><p>Each section maps the calls of a popular library to fuzzy-toolkit. Two of them have a drop-in import that keeps your code as it is. For the others, the table gives the matching call.</p><p>Two things change everywhere:</p><ul><li><strong>Scores go from 0 to 100</strong>, higher is better. A match is <code>score &gt;= threshold</code>, and the default threshold is 80.</li><li><strong>Texts are normalized first.</strong> Case, accents, punctuation, word order, missing spaces and numbers written in words (<code>two</code> = <code>2</code>) don&#39;t count against a match.</li></ul><h2 id="fuse-js" tabindex="-1">Fuse.js <a class="header-anchor" href="#fuse-js" aria-label="Permalink to &quot;Fuse.js&quot;">​</a></h2><p>Change the import and keep your code: <a href="/fuzzy-toolkit/api/#fuse-js-compatibility"><code>fuzzy-toolkit/fuse</code></a> has the Fuse.js API, including extended search, logical queries, <code>getFn</code> and <code>sortFn</code>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#F97583;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;"> Fuse </span><span style="--shiki-light:#F97583;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> &#39;fuzzy-toolkit/fuse&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // was: import Fuse from &#39;fuse.js&#39;</span></span></code></pre></div><p>To use the native API instead:</p><table tabindex="0"><thead><tr><th>Fuse.js</th><th>fuzzy-toolkit</th></tr></thead><tbody><tr><td><code>new Fuse(list, { keys })</code></td><td><code>createIndex(list, { keys, preset: &#39;search&#39; })</code></td></tr><tr><td><code>fuse.search(query, { limit })</code></td><td><code>index.search(query, { limit })</code></td></tr><tr><td><code>includeScore: true</code> (0 is perfect)</td><td>always there: <code>score</code>, 100 is perfect</td></tr><tr><td><code>includeMatches: true</code></td><td><code>includeMatches: true</code>, <code>ranges</code> with end excluded</td></tr><tr><td><code>threshold: 0.4</code> (lower is stricter)</td><td><code>threshold: 60</code> (higher is stricter)</td></tr><tr><td><code>isCaseSensitive</code>, <code>ignoreDiacritics</code></td><td><code>caseSensitive</code>, <code>accentSensitive</code> (inverted)</td></tr><tr><td><code>keys: [{ name, weight }]</code></td><td>the same</td></tr><tr><td><code>fuse.add(doc)</code>, <code>fuse.remove(fn)</code></td><td><code>index.add(item)</code>, <code>index.remove(fn)</code></td></tr><tr><td><code>Fuse.createIndex</code> / <code>Fuse.parseIndex</code></td><td><code>JSON.stringify(index)</code> / <code>loadIndex(items, saved, options)</code></td></tr></tbody></table><p>On song titles typed with a typo, fuzzy-toolkit finds 83 % of them where Fuse.js finds 65 %, 13 times faster (<a href="/fuzzy-toolkit/guide/benchmarks">benchmarks</a>).</p><h2 id="fuzzysort" tabindex="-1">fuzzysort <a class="header-anchor" href="#fuzzysort" aria-label="Permalink to &quot;fuzzysort&quot;">​</a></h2><table tabindex="0"><thead><tr><th>fuzzysort</th><th>fuzzy-toolkit</th></tr></thead><tbody><tr><td><code>fuzzysort.go(query, targets)</code></td><td><code>search(query, targets, { preset: &#39;search&#39; })</code></td></tr><tr><td><code>fuzzysort.go(query, objects, { keys: [&#39;name&#39;] })</code></td><td><code>search(query, objects, { keys: [&#39;name&#39;], preset: &#39;search&#39; })</code></td></tr><tr><td><code>{ limit, threshold }</code></td><td><code>{ limit, threshold }</code> (threshold 0 to 100)</td></tr><tr><td><code>fuzzysort.prepare(target)</code></td><td><code>createIndex(targets, options)</code>, once for the whole list</td></tr><tr><td><code>result.target</code>, <code>result.obj</code>, <code>result.score</code></td><td><code>match.text</code>, <code>match.item</code>, <code>match.score</code></td></tr><tr><td><code>result.highlight(&#39;&lt;b&gt;&#39;, &#39;&lt;/b&gt;&#39;)</code></td><td><code>highlight(match.text, query)</code>: the parts, the matching ones flagged</td></tr></tbody></table><p>fuzzysort matches the letters you typed in order, very fast. A typo in the middle of a word breaks that, and fuzzysort finds 22 % of the same typed titles. If your users never make typos, fuzzysort is faster; if they do, fuzzy-toolkit finds them.</p><h2 id="match-sorter" tabindex="-1">match-sorter <a class="header-anchor" href="#match-sorter" aria-label="Permalink to &quot;match-sorter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>match-sorter</th><th>fuzzy-toolkit</th></tr></thead><tbody><tr><td><code>matchSorter(items, value)</code></td><td><code>search(value, items, { preset: &#39;search&#39; })</code></td></tr><tr><td><code>matchSorter(items, value, { keys: [&#39;name&#39;] })</code></td><td><code>search(value, items, { keys: [&#39;name&#39;], preset: &#39;search&#39; })</code></td></tr><tr><td><code>rankings.ACRONYM</code></td><td><code>acronyms: true</code> (in the <code>search</code> preset)</td></tr><tr><td><code>rankings.CONTAINS</code></td><td><code>substring: true</code></td></tr><tr><td><code>keys: [{ key, threshold }]</code></td><td><code>keys</code> and one <code>threshold</code> for the search; <code>{ name, weight }</code> ranks a key lower</td></tr></tbody></table><p>Note the order of the arguments: the query comes first in fuzzy-toolkit. On city names typed as their initials (<code>nyc</code>), fuzzy-toolkit finds 82 % of them where match-sorter finds 59 %, 7 times faster.</p><h2 id="string-similarity" tabindex="-1">string-similarity <a class="header-anchor" href="#string-similarity" aria-label="Permalink to &quot;string-similarity&quot;">​</a></h2><p>Change the import and keep your code: <a href="/fuzzy-toolkit/api/#string-similarity-compatibility"><code>fuzzy-toolkit/string-similarity</code></a> returns exactly the same numbers, faster.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#F97583;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;"> { compareTwoStrings, findBestMatch } </span><span style="--shiki-light:#F97583;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> &#39;fuzzy-toolkit/string-similarity&#39;</span></span></code></pre></div><p>To use the native API instead:</p><table tabindex="0"><thead><tr><th>string-similarity</th><th>fuzzy-toolkit</th></tr></thead><tbody><tr><td><code>compareTwoStrings(a, b)</code> (0 to 1)</td><td><code>similarity(a, b)</code> (0 to 100), or <code>dice(a, b)</code> for the same metric</td></tr><tr><td><code>findBestMatch(main, targets).bestMatch.target</code></td><td><code>closest(main, targets)?.item</code></td></tr><tr><td><code>findBestMatch(main, targets).ratings</code></td><td><code>search(main, targets, { threshold: 0 })</code></td></tr></tbody></table><h2 id="fastest-levenshtein-and-leven" tabindex="-1">fastest-levenshtein and leven <a class="header-anchor" href="#fastest-levenshtein-and-leven" aria-label="Permalink to &quot;fastest-levenshtein and leven&quot;">​</a></h2><table tabindex="0"><thead><tr><th>fastest-levenshtein / leven</th><th>fuzzy-toolkit</th></tr></thead><tbody><tr><td><code>distance(a, b)</code> / <code>leven(a, b)</code></td><td><code>levenshtein(a, b)</code></td></tr><tr><td><code>leven(a, b, { maxDistance })</code></td><td><code>levenshtein(a, b, { max })</code>: above <code>max</code>, it returns <code>max + 1</code></td></tr><tr><td><code>closest(str, list)</code></td><td><code>closest(str, list)?.item</code> (normalized), or the list sorted by <code>levenshtein</code> (raw)</td></tr></tbody></table><p><code>levenshtein</code> is a plain edit distance, no normalization, 2 to 4 times faster than fastest-levenshtein. <code>damerau(a, b)</code> counts swapped letters as one edit.</p><h2 id="not-a-library-yet" tabindex="-1">Not a library yet? <a class="header-anchor" href="#not-a-library-yet" aria-label="Permalink to &quot;Not a library yet?&quot;">​</a></h2><p>If you hand-rolled a comparison (<code>a.toLowerCase().includes(b)</code>, a Levenshtein copied from Stack Overflow), start with <a href="/fuzzy-toolkit/guide/getting-started">Getting started</a>: <code>isMatch(a, b)</code> and <code>search(query, items)</code> cover most of it.</p>',26)])])}const y=t(a,[["render",r]]);export{u as __pageData,y as default};
